public class WoodlandPhysicalPack:MonoBehaviour {
 public WoodlandFieldKitUI kit;public WoodlandInventory inventory;public WoodlandPlayer player;public GameObject rifleModel;public GameObject radioModel,torchModel,crowbarModel,magazineModel;Transform tray;int pocketPage;const int PageSize=6;readonly List<Material> materials=new List<Material>();string hover="";bool shown;float refresh;Texture2D silhouette;readonly List<Renderer> foliage=new List<Renderer>();BodyRegion selectedRegion=BodyRegion.Chest;
 Material Mat(Color c){var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=c;materials.Add(m);return m;}
 Transform Part(Transform parent,string name,PrimitiveType type,Vector3 pos,Vector3 size,Material mat,bool collider=false){var g=GameObject.CreatePrimitive(type);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;if(!collider)Destroy(g.GetComponent<Collider>());return g.transform;}
 public void Show(){shown=true;foreach(var r in Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None)){if(r.forceRenderingOff||r.transform.IsChildOf(player.pack)||r.bounds.SqrDistance(player.pack.position)>.5f)continue;var t=r.transform;bool plant=false;for(int n=0;n<4&&t;n++,t=t.parent){string name=t.name.ToLower();if(name.Contains("fern")||name.Contains("grass")||name.Contains("undergrowth")||name.Contains("foliage"))plant=true;}if(plant){r.forceRenderingOff=true;foliage.Add(r);}}Rebuild();inventory.Changed+=Changed;}
 void Changed(){if(shown)refresh=Time.time+.05f;}
 public void Hide(){shown=false;foreach(var r in foliage)if(r)r.forceRenderingOff=false;foliage.Clear();inventory.Changed-=Changed;if(tray)Destroy(tray.gameObject);foreach(var m in materials)if(m)Destroy(m);materials.Clear();}
 void Rebuild(){if(tray)Destroy(tray.gameObject);foreach(var m in materials)if(m)Destroy(m);materials.Clear();tray=new GameObject("Physical backpack contents").transform;tray.SetParent(player.pack,false);tray.localRotation=Quaternion.Euler(0,180,0);tray.localPosition=Vector3.zero;var cloth=Mat(new Color(.09f,.105f,.065f));var dark=Mat(new Color(.025f,.03f,.028f));var paper=Mat(new Color(.57f,.56f,.42f));var green=Mat(new Color(.22f,.29f,.13f));var steel=Mat(new Color(.17f,.19f,.18f));steel.SetFloat("_Metallic",.65f);var red=Mat(new Color(.34f,.025f,.018f));
