 GameObject model=item.kind=="rifle"?rifleModel:item.kind=="radio"?radioModel:item.kind=="torch"?torchModel:item.kind=="crowbar"?crowbarModel:item.kind=="556"?magazineModel:null;
 if(model){var g=Instantiate(model,root);g.SetActive(true);foreach(var c in g.GetComponentsInChildren<Collider>())Destroy(c);foreach(var a in g.GetComponentsInChildren<MonoBehaviour>())Destroy(a);var rs=g.GetComponentsInChildren<Renderer>();if(rs.Length>0){var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);float scale=(item.kind=="rifle"?.65f:.10f)/Mathf.Max(b.size.x,b.size.y,b.size.z);g.transform.localScale*=scale;b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);g.transform.position+=root.position+Vector3.up*.025f-b.center;}}
 else if(item.kind=="filter"||item.kind=="torch_cell"||item.kind=="glowstick"){int count=Mathf.Min(item.quantity,3);for(int k=0;k<count;k++){bool filter=item.kind=="filter";var t=Part(root,"Cartridge",PrimitiveType.Cylinder,new Vector3((k-(count-1)*.5f)*.037f,.026f,0),filter?new Vector3(.05f,.03f,.05f):new Vector3(.018f,.06f,.018f),item.kind=="glowstick"?green:steel);if(!filter)t.localRotation=Quaternion.Euler(90,0,0);Part(root,"End cap",PrimitiveType.Cube,new Vector3((k-(count-1)*.5f)*.037f,.036f,.057f),new Vector3(.02f,.013f,.012f),dark);}}
 else {var size=item.kind=="map"||item.kind=="notebook"?new Vector3(.125f,.01f,.125f):new Vector3(.115f,.03f,.10f);Part(root,"Supply",PrimitiveType.Cube,new Vector3(0,.025f,0),size,item.kind=="medical"?paper:green);Part(root,"Binding",PrimitiveType.Cube,new Vector3(0,.043f,0),new Vector3(.018f,.005f,.105f),dark);if(item.kind=="medical"){Part(root,"Medical cross",PrimitiveType.Cube,new Vector3(.026f,.045f,0),new Vector3(.035f,.004f,.01f),red);Part(root,"Medical cross",PrimitiveType.Cube,new Vector3(.026f,.046f,0),new Vector3(.01f,.004f,.035f),red);}}
 }
 }
 void Update(){if(WoodlandDemoControls.Paused)return;if(!shown)return;if(Gamepad.current!=null){int count=inventory.data.items.FindAll(i=>i.container=="carry"&&i.kind!="suit"&&i.kind!="backpack"&&i.kind!="rifle"&&i.kind!="notebook").Count;int pages=Mathf.Max(1,Mathf.CeilToInt(count/6f));if(Gamepad.current.dpad.right.wasPressedThisFrame){pocketPage=(pocketPage+1)%pages;Rebuild();}if(Gamepad.current.dpad.left.wasPressedThisFrame){pocketPage=(pocketPage+pages-1)%pages;Rebuild();}}if(refresh>0&&Time.time>=refresh){refresh=0;Rebuild();}hover="";if(Mouse.current==null)return;if(EventSystem.current&&EventSystem.current.IsPointerOverGameObject())return;var ray=player.eye.ScreenPointToRay(Mouse.current.position.ReadValue());if(Physics.Raycast(ray,out var hit,4)){var item=hit.collider.GetComponentInParent<WoodlandPackItem>();if(item){var data=inventory.data.items.Find(x=>x.id==item.id);if(data!=null)hover=inventory.defs[data.kind].name+" ×"+data.quantity+" · Click to select";if(Mouse.current.leftButton.wasPressedThisFrame)kit.SelectPhysical(item.id);}}
 }
